const PEN2 = 'M5 5h14v14H5zM9.7 5v14M14.3 5v14';

// hover in the task's words: who, state with when, and the recorded reason only when it explains the state
const hov2 = (x, y, w, head, sub, lines) => card({ left: x + 'px', top: y + 'px', width: w + 'px' }, '<div style="padding: 10px 12px 11px;"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 8px;">' + t(head, { fontWeight: 600 }) + mu(sub, { fontSize: '12px' }) + '</div><div style="height: 1px; background: ' + K.line + '; margin: 8px 0 7px;"></div>' + lines.map((l) => '<div style="display: flex; align-items: center; gap: 8px; padding: 2px 0; font-size: 13px; line-height: 18px;">' + l[0] + '<span style="flex: 1; color: ' + (l[2] || K.ink) + '; font-weight: ' + (l[3] ? 600 : 400) + ';">' + l[1] + '</span></div>').join('') + '</div>');
const mini = (kind) => { const m = { done: [DF, DFI, '✓'], skip: [AF, AFI, '1'], due: [PF, PFI, '2'], next: ['#FFFFFF', K.muted, '3'] }[kind]; return '<span style="' + st({ display: 'inline-grid', placeItems: 'center', width: '16px', height: '16px', borderRadius: '99px', background: m[0], color: m[1], boxShadow: kind === 'next' ? 'inset 0 0 0 1.5px ' + HANDLE : 'none', fontSize: '10px', fontWeight: 700, flex: 'none' }) + '">' + m[2] + '</span>'; };
const rxPane2 = () => paneSlim(thead({ title: 'Treatment RX-25G009', sub: 'Amoxicillin · dose 2 of 3 today' }), gauge([[DM, 'Given', 2], [PM, 'Due', 1], [LM, 'Skipped', 1]], 4, '2', 'of 4 sows') + '<div style="display: flex; gap: 8px; margin-top: 12px;">' + fbtn(ic(SC2.ext, 15) + '&nbsp; Open page') + '</div>');

// D41: skipped, due today
const d41 = () => paneSlim(backHead('Treatment RX-25G009'),
  who('D41 · 205901', 'Sow · P4 · Pen D41', I.pig, openProfile) +
  card2(mu('Amoxicillin 15% LA · 15 mL in the neck', { display: 'block', fontSize: '12.5px', marginBottom: '12px' }) + track([['skip', '1', 'Skipped', 'Thu 08:40'], ['due', '2', 'Due today', '08:30'], ['next', '3', 'Planned', 'Sat 08:30']]) +
    '<div style="display: flex; align-items: center; gap: 8px; margin-top: 14px; padding-top: 12px; border-top: 1px solid ' + K.line + ';">' + ic(SHIELD, 15, 1.8, K.muted) + mu('Withdrawal ends 21 Nov, if dose 3 is on Sat', { fontSize: '12.5px', whiteSpace: 'normal' }) + '</div>') +
  sec('Log') + card2(logT([
    { day: 'Wed', time: '16:10', col: NM, title: 'Prescribed · 3 doses', who: ['VT', '#DDF1EF', '#1F6F68'], chips: [chipT('Lameness'), chipT('Fever 40.1 °C')] },
    { day: 'Thu', time: '08:40', col: AMB, title: 'Dose 1 skipped', who: ['GH'], chips: [chipT('Could not stand', 'amb')] },
    { day: 'Fri', time: '07:55', col: NM, title: 'Response checked', who: ['LW'], chips: [chipT('Lameness score 3')] }
  ]), '6px 14px'));
// Pen B12: a group pen treated by rounds; tagged pigs named, the rest counted
const ring3 = (g, a, n) => { const C = 2 * Math.PI * 11, gl = C * g / n, al = C * a / n; return '<svg viewBox="0 0 30 30" style="width: 30px; height: 30px; position: relative; z-index: 1;"><circle cx="15" cy="15" r="11" fill="#FFFFFF" stroke="' + HANDLE + '" stroke-width="5"></circle>' + (g ? '<circle cx="15" cy="15" r="11" fill="none" stroke="' + GRN + '" stroke-width="5" stroke-dasharray="' + gl.toFixed(1) + ' ' + C.toFixed(1) + '" transform="rotate(-90 15 15)"></circle>' : '') + (a ? '<circle cx="15" cy="15" r="11" fill="none" stroke="' + LM + '" stroke-width="5" stroke-dasharray="' + al.toFixed(1) + ' ' + C.toFixed(1) + '" stroke-dashoffset="' + (-gl).toFixed(1) + '" transform="rotate(-90 15 15)"></circle>' : '') + '</svg>'; };
const trackG = (steps) => { const n = steps.length; return '<div style="position: relative; display: grid; grid-template-columns: repeat(' + n + ', 1fr); margin-top: 4px;"><div style="' + st({ position: 'absolute', left: (50 / n) + '%', right: (50 / n) + '%', top: '15px', height: '2px', background: '#E3E6DF' }) + '"></div>' + steps.map((s) => '<div style="display: flex; flex-direction: column; align-items: center; gap: 6px; text-align: center;">' + (s[0] === 'due' ? node('due', '') : ring3(s[1], s[2], 9)) + '<span style="display: flex; flex-direction: column;">' + t(s[3], { fontSize: '12.5px', fontWeight: 600, color: K.ink }) + t(s[4], { fontSize: '11.5px', color: K.muted }) + '</span></div>').join('') + '</div>'; };
const tag = (s) => chipT(s, 'blu');
const b12 = () => paneSlim(backHead('Treatment RX-25G011'),
  who('Pen B12', '9 weaners · Nursery 1', PEN2) +
  card2(mu('Florfenicol · 1 mL each, 3 days', { display: 'block', fontSize: '12.5px', marginBottom: '12px' }) + trackG([['done', 9, 0, 'Day 1', '9 given'], ['part', 7, 2, 'Day 2', '7 given, 2 skipped'], ['due', 0, 0, 'Day 3', 'Due today']])) +
  sec('Log') + card2(logT([
    { day: 'Wed', time: '08:05', col: GRN, title: 'Day 1: 9 given', who: ['GH'] },
    { day: 'Thu', time: '08:12', col: GRN, title: 'Day 2: 7 given', who: ['GH'] },
    { day: 'Thu', time: '08:14', col: AMB, title: 'Day 2: 2 skipped', who: ['GH'], chips: [chipT('Could not catch', 'amb'), tag('310422'), chipT('1 untagged')] }
  ]), '6px 14px'));

frames.r1 = { bg: 'tx', cap: 'The task on the map: the pane holds the treatment and its states in its own words (Given, Due, Skipped). Hover D41: who she is, where she is now in this treatment, and the recorded reason, nothing else.', html: () => tabsStrip('Farm view') + fbar() + rxPane2() + vctl + hov2(372, 436, 252, 'D41 · 205901', 'Sow · P4', [[mini('due'), 'Dose 2 due today 08:30', K.ink, true], [mini('skip'), 'Dose 1 skipped: could not stand', K.ink]]) };
frames.r2 = { bg: 'tx', cap: 'Click D41: this treatment, for her. The dose track says where she is at a glance; the log says how she got here, every entry recorded in this treatment, with who. Her record, other tasks and moves are on her profile.', html: () => tabsStrip('Farm view') + fbar() + vctl + d41() };
frames.r3 = { bg: 'zb12', cap: 'A group pen in a treatment: each day a ring, given and skipped. The log names tagged pigs and counts the rest; a tag opens her profile.', html: () => tabsStrip('Farm view').replace('Treatment RX-25G009', 'Treatment RX-25G011') + penBar('9', 'Pen B12') + vctl + b12() };
(async () => {
  const W = 950, Hh = 830, gap = 40, pad = 48;
  const frame = async (k, n) => {
    const f = frames[k]; let img = '';
    if (f.bg) { const b = await sharp(path.join(bgDir, 'L3JS_' + f.bg + '_950.png')).jpeg({ quality: 80 }).toBuffer(); img = '<img alt="" src="data:image/jpeg;base64,' + b.toString('base64') + '" style="position: absolute; inset: 0; width: ' + W + 'px; height: ' + Hh + 'px;">'; }
    return '<figure style="margin: 0; width: ' + W + 'px;"><div style="' + st({ position: 'relative', width: W + 'px', height: Hh + 'px', overflow: 'hidden', borderRadius: '16px', background: K.tint, boxShadow: '0 0 0 1px #D9DDD3, 0 10px 30px rgba(17,21,17,.10)', fontFamily: "'Geist', system-ui, sans-serif", color: K.ink, fontSize: '14px', lineHeight: '20px', fontVariantNumeric: 'tabular-nums' }) + '">' + img + f.html() + '</div><figcaption style="margin-top: 12px; font-size: 14px; line-height: 21px; color: #3B4540;"><b style="font-weight: 600; color: #111511;">' + n + '</b> · ' + esc(f.cap) + '</figcaption></figure>';
  };
  const rules = [
    ['Words from the task', 'Treatment says Given, Due, Skipped. No generic labels (To do, Needs a look). Colours follow the mobile convention: green done, blue today, amber skipped; tonal fills for shapes, marks for thin parts, ink for words.'],
    ['Hover: where she is now', 'Who; her state in this task with when; the recorded reason only if it explains the state. Nothing outside the task.'],
    ['Click: this task, for her', 'A track of the task\'s steps, then the log of what was recorded in this task, with who. No moves, no other tasks, no next task: those are on her profile, one button away.'],
    ['Group pens', 'The same view for the pen: a ring per round (given, skipped), a log that names tagged pigs and counts the rest.']
  ];
  const body = '<h1 style="margin: 0; font-size: 28px; line-height: 36px; font-weight: 600; letter-spacing: -.02em;">Treatment on the Farm view</h1><div style="margin-top: 6px; font-size: 15px; line-height: 22px; color: #5D665F;">What the hover says and what the task-pig view holds, for a sow and for a group pen. Panes are 320 wide (display). The chat stays on the left.</div>' +
    '<div style="display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-top: 22px;">' + rules.map((r, i) => '<div style="padding: 16px 18px; background: #FFFFFF; border: 1px solid #DFE4D8; border-radius: 16px;"><div style="font-size: 15px; font-weight: 600;">' + (i + 1) + '. ' + r[0] + '</div><div style="margin-top: 4px; font-size: 14px; line-height: 21px; color: #3B4540;">' + esc(r[1]) + '</div></div>').join('') + '</div>' +
    '<div style="display: flex; gap: ' + gap + 'px; align-items: flex-start; margin-top: 36px;">' + (await Promise.all(['r1', 'r2', 'r3'].map((k, i) => frame(k, i + 1)))).join('') + '</div>';
  const BW = 3 * W + 2 * gap + 2 * pad;
  const sh = fs.readFileSync(shell, 'utf8'), pre = sh.slice(0, sh.indexOf('<div style="width: 1760px;')).replace(/<title>[^<]*<\/title>/, '<title>Treatment on the Farm view</title>');
  const html = pre + '<div style="width: ' + BW + 'px; padding: 40px ' + pad + 'px 64px; box-sizing: border-box; background: #F3F4F1; font-family: \'Geist\', system-ui, sans-serif; color: #111511; -webkit-font-smoothing: antialiased;">' + body + '</div>\n</x-dc>\n</body>\n</html>\n';
  fs.writeFileSync(out, html); console.log('wrote', out, Math.round(html.length / 1024) + ' KB', 'width', BW);
})();
